import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    s = data[1] if len(data) > 1 else ""

    i = 0
    result = []

    while i < n:
        if i + 2 < n and s[i:i+3] == "ogo":
            j = i + 3
            while j + 1 < n and s[j:j+2] == "go":
                j += 2
            result.append("***")
            i = j
        else:
            result.append(s[i])
            i += 1

    print("".join(result))

if __name__ == "__main__":
    main()
